<?php require_role('admin');require_once 'app/helpers.php';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=[(int)$_POST['subtopic_id'],trim($_POST['title_en']),trim($_POST['title_ta']),trim($_POST['body_en']),trim($_POST['body_ta']),trim($_POST['references_text'])];if($id){$s=db()->prepare('UPDATE contents SET subtopic_id=?,title_en=?,title_ta=?,body_en=?,body_ta=?,references_text=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([...$d,$id]);}else{$s=db()->prepare('INSERT INTO contents(subtopic_id,title_en,title_ta,body_en,body_ta,references_text) VALUES(?,?,?,?,?,?)');$s->execute($d);}header('Location: admin_content.php');exit;}$subs=db()->query("SELECT s.id,s.title_en subtopic,t.title_en topic,t.audience FROM subtopics s JOIN topics t ON t.id=s.topic_id ORDER BY t.audience,t.title_en,s.sort_order")->fetchAll();$c=$id?db()->query('SELECT * FROM contents WHERE id='.$id)->fetch():['subtopic_id'=>(int)($_GET['subtopic_id']??0),'title_en'=>'','title_ta'=>'','body_en'=>'','body_ta'=>'','references_text'=>''];$page_title='Content Editor';include 'partials/header.php';?><div class="card"><h1><?=($id?'Edit':'Add')?> Knowledge Content</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-group"><label>Subtopic</label><select name="subtopic_id" required><?php foreach($subs as $x):?><option value="<?=$x['id']?>" <?=$c['subtopic_id']==$x['id']?'selected':''?>><?=e($x['audience'].' – '.$x['topic'].' – '.$x['subtopic'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Title (English)</label><input name="title_en" value="<?=e($c['title_en'])?>" required></div><div class="form-group"><label>Title (Tamil)</label><input name="title_ta" value="<?=e($c['title_ta'])?>"></div><div class="form-group"><label>Detailed content (English)</label><textarea name="body_en" required><?=e($c['body_en'])?></textarea></div><div class="form-group"><label>Detailed content (Tamil)</label><textarea name="body_ta"><?=e($c['body_ta'])?></textarea></div><div class="form-group"><label>References</label><textarea name="references_text"><?=e($c['references_text'])?></textarea></div><button class="btn">Save content</button> <a class="btn secondary" href="admin.php">Cancel</a></form></div><?php include 'partials/footer.php';?>
